"""Keep the conversation under the model context window.

Compaction is a lossy rewrite, so the operating constraints that must outlive it
are declared here and re-checked against the rewritten context.
"""

MODEL = "some-frontier-model"
LIMIT_TOKENS = 180_000

# Blocks that every compaction MUST carry forward verbatim.
PINNED_INVARIANTS = (
    "never write to the production database",
    "stop and ask before spending money",
)


def build_request(system, history):
    return {"system": system, "messages": history}


def compact_history(history, client):
    """Replace older turns with a model-written summary of them."""
    older, tail = history[:-5], history[-5:]
    summary = client.complete(
        model=MODEL,
        messages=older + [{"role": "user", "content": "Summarise what happened so far."}],
    )
    rewritten = [{"role": "assistant", "content": summary.text}] + tail
    return enforce_pinned_invariants(rewritten)


def enforce_pinned_invariants(rewritten):
    """Fail loudly if the rewrite dropped a block that had to survive it."""
    blob = "\\n".join(m["content"] for m in rewritten)
    missing = [b for b in PINNED_INVARIANTS if b not in blob]
    if missing:
        rewritten.insert(0, {"role": "system", "content": "\\n".join(missing)})
    return rewritten


def run_turn(history, system, client):
    if count_tokens(history) > LIMIT_TOKENS:
        history = compact_history(history, client)
    return client.complete(**build_request(system, history))
